/**
 * Validate a flat Bricks content array (the shape of `_bricks_page_content_2`,
 * or of stage 3's bricks-tree.json output) before it's ever sent to WordPress.
 *
 * Ground truth comes from schema/bricks-elements.json and
 * schema/bricks-settings.json — both generated BY bricks-analyzer.js FROM
 * your real homepage.json export, not hand-written. Re-run the analyzer on
 * more real pages and this validator gets stricter/more accurate for free.
 *
 * Usage:
 *   node scripts/bricks-validator.js <path-to-bricks-json-array>
 *   node scripts/bricks-validator.js            (self-test against homepage.json's content array)
 *
 * Checks performed:
 *   1. Input is an array
 *   2. Every element has a unique, well-formed id
 *   3. Every `parent` is 0 or an id that exists in the array
 *   4. No circular parent chains
 *   5. Every id listed in `children` actually exists, and is consistent
 *      with that child's own `parent` pointer (both directions must agree)
 *   6. `settings` is an object (or absent)
 *   7. `name` is a known element type (warning, not hard failure — new
 *      element types are expected as you feed in more real pages)
 *   8. Responsive/pseudo setting key suffixes match previously observed
 *      breakpoints/pseudo-selectors (warning if a new one appears)
 *   9. image / icon / link settings match one of the observed real shapes
 */
import fs from "fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const schemaDir = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..", "schema");
const ELEMENTS_SCHEMA_PATH = path.join(schemaDir, "bricks-elements.json");
const SETTINGS_SCHEMA_PATH = path.join(schemaDir, "bricks-settings.json");

function loadJson(p, label) {
  if (!fs.existsSync(p)) {
    console.error(`Missing ${label}: ${p}`);
    console.error("Run scripts/bricks-analyzer.js against a real export first.");
    process.exit(1);
  }
  return JSON.parse(fs.readFileSync(p, "utf8"));
}

const elementsSchema = loadJson(ELEMENTS_SCHEMA_PATH, "elements schema");
const settingsSchema = loadJson(SETTINGS_SCHEMA_PATH, "settings schema");

const knownElementTypes = new Set(Object.keys(elementsSchema));

// Base setting keys actually observed per element type, with any responsive
// (":tablet_portrait") or pseudo ("::after") suffix stripped. Used to flag
// keys the compiler emits that have never appeared in a real export.
const knownKeysByType = {};
const runtimeTypes = new Set();
for (const [type, info] of Object.entries(elementsSchema)) {
  knownKeysByType[type] = new Set(
    (info.observedSettingKeys || []).map((o) => o.key.split(":")[0])
  );
}

// Extract known breakpoint suffixes from the observed responsive key list,
// e.g. "_padding:tablet_portrait" -> "tablet_portrait". (Excludes pseudo
// keys like "_content::after", which use "::" not ":" and are handled separately.)
const knownBreakpoints = new Set(
  settingsSchema.responsiveKeys
    .filter((k) => k.includes(":") && !k.includes("::"))
    .map((k) => k.split(":").pop())
);
const knownPseudoSuffixes = new Set(["::before", "::after"]);

// Keys proven by rendering in real Bricks but absent from analyzed exports (hand-maintained).
const VERIFIED_PATH = path.join(schemaDir, "bricks-verified-keys.json");
if (fs.existsSync(VERIFIED_PATH)) {
  const verified = JSON.parse(fs.readFileSync(VERIFIED_PATH, "utf8"));
  for (const [type, keys] of Object.entries(verified)) {
    if (type.startsWith("_") || !Array.isArray(keys)) continue;
    knownKeysByType[type] = knownKeysByType[type] || new Set();
    for (const k of keys) knownKeysByType[type].add(k);
  }
}
const runtimeManifest = path.join(schemaDir, "runtime", "manifest.json");
if (fs.existsSync(runtimeManifest)) {
  const manifest = loadJson(runtimeManifest, "runtime manifest");
  for (const type of manifest.elements || []) {
    const schema = loadJson(path.join(schemaDir, "runtime", `${type}.json`), `${type} runtime schema`);
    if (schema.name !== type || !schema.controls) throw new Error(`Invalid runtime schema for ${type}`);
    knownKeysByType[type] = new Set(Object.keys(schema.controls)); runtimeTypes.add(type); knownElementTypes.add(type);
  }
}

function isPlainObject(v) {
  return v !== null && typeof v === "object" && !Array.isArray(v);
}

export function validateBricks(tree) {
  const errors = [];
  const warnings = [];

  if (!Array.isArray(tree)) {
    errors.push("Root value is not an array — Bricks content must be a flat array.");
    return { errors, warnings };
  }

  const byId = new Map();
  const idCounts = {};

  // Pass 1: basic shape + id collection
  for (const [i, el] of tree.entries()) {
    if (!isPlainObject(el)) {
      errors.push(`Element at index ${i} is not an object.`);
      continue;
    }
    if (!el.id || typeof el.id !== "string") {
      errors.push(`Element at index ${i} (name: ${el.name || "?"}) has a missing/invalid id.`);
      continue;
    }
    idCounts[el.id] = (idCounts[el.id] || 0) + 1;
    byId.set(el.id, el);

    if (!el.name) {
      errors.push(`Element ${el.id} has no "name".`);
    } else if (!knownElementTypes.has(el.name)) {
      warnings.push(
        `Element ${el.id}: name "${el.name}" is not in the observed element types ` +
          `(${[...knownElementTypes].join(", ")}). Might be new/valid — re-run the ` +
          `analyzer on a page containing it to confirm its settings shape.`
      );
    }

    if (el.settings !== undefined && !isPlainObject(el.settings)) {
      errors.push(`Element ${el.id}: "settings" must be an object, got ${typeof el.settings}.`);
    }

    if (el.children !== undefined && !Array.isArray(el.children)) {
      errors.push(`Element ${el.id}: "children" must be an array of id strings.`);
    }
  }

  for (const [id, count] of Object.entries(idCounts)) {
    if (count > 1) errors.push(`Duplicate id "${id}" appears ${count} times.`);
  }

  // Pass 2: parent/children consistency
  for (const el of tree) {
    if (!el || !el.id) continue;

    if (el.parent !== 0 && el.parent !== undefined) {
      if (typeof el.parent !== "string") {
        errors.push(`Element ${el.id}: "parent" must be 0 or an id string, got ${JSON.stringify(el.parent)}.`);
      } else if (!byId.has(el.parent)) {
        errors.push(`Element ${el.id}: parent "${el.parent}" does not exist in this tree.`);
      }
    }

    const childIds = Array.isArray(el.children) ? el.children : [];
    if (new Set(childIds).size !== childIds.length) errors.push(`Element ${el.id}: duplicate child ids.`);
    const parent = byId.get(el.parent);
    if (parent && !(Array.isArray(parent.children) && parent.children.includes(el.id))) errors.push(`Element ${el.id}: parent ${el.parent} does not list it as a child.`);
    for (const childId of childIds) {
      if (typeof childId !== "string") {
        errors.push(`Element ${el.id}: children array contains a non-string value.`);
        continue;
      }
      const child = byId.get(childId);
      if (!child) {
        errors.push(`Element ${el.id}: lists child "${childId}" which does not exist in this tree.`);
        continue;
      }
      if (child.parent !== el.id) {
        errors.push(
          `Element ${el.id} lists "${childId}" as a child, but ${childId}.parent is ` +
            `"${child.parent}" (should be "${el.id}"). parent/children pointers disagree.`
        );
      }
    }
  }

  // Pass 3: circular parent chains
  for (const el of tree) {
    if (!el || !el.id) continue;
    const seen = new Set();
    let cur = el;
    let hops = 0;
    while (cur && cur.parent && cur.parent !== 0) {
      if (seen.has(cur.id)) {
        errors.push(`Circular parent chain detected starting at "${el.id}".`);
        break;
      }
      seen.add(cur.id);
      cur = byId.get(cur.parent);
      hops++;
      if (hops > tree.length) {
        errors.push(`Parent chain from "${el.id}" exceeds tree size — likely circular.`);
        break;
      }
    }
  }

  // Pass 4: setting key suffix + known special-structure checks
  for (const el of tree) {
    if (!el || !isPlainObject(el.settings)) continue;

    for (const key of Object.keys(el.settings)) {
      const baseKey = key.split(":")[0];
      const known = knownKeysByType[el.name];
      if (known && !known.has(baseKey)) {
        warnings.push(
          runtimeTypes.has(el.name)
            ? `Element ${el.id} (${el.name}): setting "${key}" is absent from the saved runtime control schema; confirm support before writing.`
            : `Element ${el.id} (${el.name}): setting "${key}" is absent from the sampled exports; site support has not been established.`
        );
      }
      if (key.includes("::")) {
        const suffix = "::" + key.split("::")[1];
        if (!knownPseudoSuffixes.has(suffix)) {
          warnings.push(`Element ${el.id}: unrecognized pseudo-suffix "${suffix}" on key "${key}".`);
        }
      } else if (key.includes(":")) {
        const bp = key.split(":").pop();
        if (!knownBreakpoints.has(bp)) {
          warnings.push(
            `Element ${el.id}: unrecognized breakpoint "${bp}" on key "${key}" ` +
              `(known: ${[...knownBreakpoints].join(", ")}).`
          );
        }
      }
    }

    checkSpecialShape(el, "image", ["id", "filename", "size", "full", "url"], warnings);
    checkLinkShape(el, warnings);
  }

  return { errors, warnings };
}

function checkSpecialShape(el, key, requiredKeys, warnings) {
  const value = el.settings[key];
  if (value === undefined) return;
  if (!isPlainObject(value)) {
    warnings.push(`Element ${el.id}: settings.${key} should be an object, got ${typeof value}.`);
    return;
  }
  if (requiredKeys) {
    const missing = requiredKeys.filter((k) => !(k in value));
    if (missing.length) {
      warnings.push(`Element ${el.id}: settings.${key} is missing expected keys: ${missing.join(", ")}.`);
    }
  }
}

function checkLinkShape(el, warnings) {
  const link = el.settings.link;
  if (link === undefined) return;
  if (!isPlainObject(link)) {
    warnings.push(`Element ${el.id}: settings.link should be an object, got ${typeof link}.`);
    return;
  }
  // Observed real shapes: {type:"external", url, postId} and {type:"internal", postId}
  // (no "url" on internal links — resolved via postId instead).
  if (!link.type) {
    warnings.push(`Element ${el.id}: settings.link has no "type".`);
  } else if (link.type === "external" && !link.url) {
    warnings.push(`Element ${el.id}: settings.link type "external" but no "url" set.`);
  } else if (link.type === "internal" && !link.postId) {
    warnings.push(`Element ${el.id}: settings.link type "internal" but no "postId" set.`);
  }
}

// --------------------------------------------------
// CLI
// --------------------------------------------------

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
const inputArg = process.argv[2];
let tree;
let sourceLabel;

if (inputArg) {
  tree = loadJson(inputArg, "input file");
  sourceLabel = inputArg;
} else {
  console.log("No input given — self-testing against homepage.json's content array.");
  const homepage = loadJson("./homepage.json", "homepage.json");
  tree = homepage.content;
  sourceLabel = "homepage.json (content)";
}

// Accept a full template envelope ({ content: [...] }) as well as a bare array.
if (!Array.isArray(tree) && tree && Array.isArray(tree.content)) tree = tree.content;

console.log("");
console.log("======================================");
console.log("        BRICKS JSON VALIDATOR");
console.log("======================================");
console.log("");
console.log("Input:", sourceLabel);
console.log("Elements:", Array.isArray(tree) ? tree.length : "N/A");
console.log("");

const { errors, warnings } = validateBricks(tree);

if (errors.length) {
  console.log(`✗ ${errors.length} error(s):`);
  for (const e of errors) console.log("  -", e);
} else {
  console.log("✓ No structural errors.");
}

console.log("");
if (warnings.length) {
  console.log(`⚠ ${warnings.length} warning(s):`);
  for (const w of warnings.slice(0, 30)) console.log("  -", w);
  if (warnings.length > 30) console.log(`  ... and ${warnings.length - 30} more.`);
} else {
  console.log("No warnings.");
}

console.log("");
process.exit(errors.length ? 1 : 0);
}
